import { createError } from "../composables/error.js";
const intervalError = "[nuxt] `setInterval` should not be used on the server. Consider wrapping it with an `onNuxtReady`, `onBeforeMount` or `onMounted` lifecycle hook, or ensure you only call it in the browser by checking `import.meta.client`.";
export const setInterval = import.meta.client ? globalThis.setInterval : (() => {
  if (import.meta.dev) {
    throw createError({
      status: 500,
      message: intervalError
    });
  }
  console.error(intervalError);
});
<script setup lang="ts">
/**
 * Connection status.
 *
 * A reader who loses signal mid-article should be told, not left wondering why
 * nothing loads. The bar also confirms recovery, then gets out of the way.
 *
 * State is read on the client only: on the server there is no navigator, and
 * defaulting to offline would flash the bar at every reader on first paint.
 */
const online = ref(true)
const showRestored = ref(false)
let timer: ReturnType<typeof setTimeout> | null = null

function sync() {
  const next = navigator.onLine
  if (next === online.value) return

  online.value = next
  if (next) {
    showRestored.value = true
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => { showRestored.value = false }, 4000)
  } else {
    showRestored.value = false
  }
}

onMounted(() => {
  online.value = navigator.onLine
  window.addEventListener('online', sync)
  window.addEventListener('offline', sync)
})

onBeforeUnmount(() => {
  window.removeEventListener('online', sync)
  window.removeEventListener('offline', sync)
  if (timer) clearTimeout(timer)
})

const { t } = useLocale()

const visible = computed(() => !online.value || showRestored.value)
</script>

<template>
  <div
    v-if="visible"
    :class="[
      'fixed inset-x-0 top-0 z-[90] px-4 py-2 text-center text-sm font-semibold text-white',
      'animate-slide-down',
      online ? 'bg-success' : 'bg-ink',
    ]"
    role="status"
    aria-live="polite"
    data-testid="offline-banner"
  >
    <template v-if="online">
      {{ t('backOnline') }}
    </template>
    <template v-else>
      {{ t('offline') }}
    </template>
  </div>
</template>
<script setup lang="ts">
import type { ArticleCard } from '~/types'

/**
 * The red breaking bar (§7). Server-rendered from the initial fetch, then kept
 * current by the WebSocket so a reader who leaves the tab open sees a new
 * alert without refreshing.
 */
const props = defineProps<{ initial?: ArticleCard[] }>()

const store = useBreakingStore()
const { t, title: localTitle } = useLocale()

// Fetch on the server when no list was handed down, so the bar is in the
// initial HTML rather than popping in after hydration.
if (props.initial?.length) {
  store.setItems(props.initial)
} else {
  const { data } = await useAsyncApi<ArticleCard[]>('breaking-bar', '/api/breaking')
  if (data.value?.length) store.setItems(data.value)
}

// The socket writes into the same store, so the bar updates in place.
const { connected } = useBreakingSocket()

const index = ref(0)
let rotator: ReturnType<typeof setInterval> | null = null

const items = computed(() => store.items)
const current = computed(() => items.value[index.value] ?? null)

// Rotate through alerts when there is more than one, pausing on hover so a
// reader can actually click the headline they were reading.
const paused = ref(false)

function startRotation() {
  stopRotation()
  if (items.value.length < 2) return
  rotator = setInterval(() => {
    if (!paused.value) index.value = (index.value + 1) % items.value.length
  }, 6000)
}
function stopRotation() {
  if (rotator) { clearInterval(rotator); rotator = null }
}

watch(items, () => {
  index.value = 0
  startRotation()
}, { immediate: true })

onBeforeUnmount(stopRotation)
</script>

<template>
  <div
    v-if="current"
    class="border-b border-breaking/20 bg-breaking text-white"
    role="region"
    :aria-label="t('breakingRegion')"
    @mouseenter="paused = true"
    @mouseleave="paused = false"
  >
    <div class="container-content flex items-center gap-3 py-2">
      <span class="flex shrink-0 items-center gap-1.5 text-xs font-bold uppercase tracking-wide">
        <span class="inline-block h-2 w-2 rounded-full bg-white animate-pulse-dot" aria-hidden="true" />
        {{ t('breaking') }}
      </span>

      <!-- aria-live so a screen reader announces a pushed alert, but polite so
           it does not interrupt whatever the reader is already hearing. -->
      <div class="min-w-0 flex-1" aria-live="polite" aria-atomic="true">
        <NuxtLink
          :to="`/news/${current.slug}`"
          class="block truncate text-kh-sm font-semibold hover:underline"
        >
          {{ localTitle(current) }}
        </NuxtLink>
      </div>

      <div v-if="items.length > 1" class="hidden shrink-0 items-center gap-1 sm:flex">
        <button
          v-for="(item, i) in items.slice(0, 5)"
          :key="item.id"
          :class="['h-1.5 rounded-full transition-all', i === index ? 'w-4 bg-white' : 'w-1.5 bg-white/50']"
          :aria-label="t('breakingItemAria', { n: i + 1 })"
          @click="index = i"
        />
      </div>

      <NuxtLink to="/live" class="hidden shrink-0 text-xs font-semibold underline underline-offset-2 sm:block">
        {{ t('viewAll') }}
      </NuxtLink>

      <!-- Connection state is shown only when the live channel is down, so the
           bar does not imply real-time updates it is not receiving. -->
      <span
        v-if="!connected"
        class="hidden shrink-0 text-[10px] opacity-70 lg:block"
        title="Live updates unavailable; refreshing periodically"
      >offline</span>
    </div>
  </div>
</template>
<script setup lang="ts">
const { t } = useLocale()

/**
 * Optional mobile sticky unit (§39).
 *
 * It is dismissible, remembers the dismissal for the session, and respects the
 * safe-area inset so it never sits under a phone's home indicator. The slot is
 * disabled by default in the seed — turning it on is a deliberate decision.
 */
const dismissed = ref(false)
const STORAGE_KEY = 'cfn.sticky-ad.dismissed'

onMounted(() => {
  try {
    dismissed.value = sessionStorage.getItem(STORAGE_KEY) === '1'
  } catch {
    // Private mode or blocked storage: show the ad, it is still dismissible.
  }
})

function dismiss() {
  dismissed.value = true
  try {
    sessionStorage.setItem(STORAGE_KEY, '1')
  } catch {
    // Not being able to remember the dismissal is acceptable; ignoring the
    // dismissal would not be.
  }
}
</script>

<template>
  <div
    v-if="!dismissed"
    class="fixed inset-x-0 bottom-0 z-40 border-t border-line bg-surface/95 backdrop-blur lg:hidden"
    style="padding-bottom: env(safe-area-inset-bottom)"
  >
    <div class="relative flex justify-center py-1">
      <button
        class="absolute -top-7 right-2 rounded-full bg-ink/80 p-1.5 text-white"
        :aria-label="t('closeAd')"
        @click="dismiss"
      >
        <svg class="h-3.5 w-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3" aria-hidden="true">
          <path d="M6 6l12 12M18 6L6 18" stroke-linecap="round" />
        </svg>
      </button>

      <AdSlot position="MOBILE_STICKY" collapse-when-empty class="!my-0" />
    </div>
  </div>
</template>
/** Web Push subscription management (§30). */
export function usePush() {
  const api = useApi()

  const supported = computed(() =>
    import.meta.client &&
    'serviceWorker' in navigator &&
    'PushManager' in window &&
    'Notification' in window,
  )

  const permission = ref<NotificationPermission>('default')
  const subscribed = ref(false)

  onMounted(async () => {
    if (!supported.value) return
    permission.value = Notification.permission
    try {
      const registration = await navigator.serviceWorker.ready
      subscribed.value = Boolean(await registration.pushManager.getSubscription())
    } catch {
      subscribed.value = false
    }
  })

  /** VAPID keys are base64url; PushManager wants a Uint8Array. */
  // Returns an ArrayBuffer rather than a Uint8Array: pushManager.subscribe
  // wants a BufferSource backed by a plain ArrayBuffer, and Uint8Array.from
  // gives one typed over ArrayBufferLike, which includes SharedArrayBuffer and
  // so is not assignable.
  function urlBase64ToBuffer(base64: string): ArrayBuffer {
    const padding = '='.repeat((4 - (base64.length % 4)) % 4)
    const normalized = (base64 + padding).replace(/-/g, '+').replace(/_/g, '/')
    const raw = atob(normalized)
    const buffer = new ArrayBuffer(raw.length)
    const view = new Uint8Array(buffer)
    for (let i = 0; i < raw.length; i += 1) view[i] = raw.charCodeAt(i)
    return buffer
  }

  /**
   * Subscribes to the chosen topics. Must be called from a user gesture —
   * browsers reject (and remember) permission requests that are not.
   */
  async function subscribe(topics: string[]): Promise<boolean> {
    if (!supported.value) return false

    const { publicKey, configured } = await api.get<{ publicKey: string; configured: boolean }>('/api/push/key')
    if (!configured || !publicKey) return false

    permission.value = await Notification.requestPermission()
    if (permission.value !== 'granted') return false

    const registration = await navigator.serviceWorker.ready
    const subscription = await registration.pushManager.subscribe({
      userVisibleOnly: true,
      applicationServerKey: urlBase64ToBuffer(publicKey),
    })

    const payload = subscription.toJSON()
    await api.post('/api/push/subscribe', {
      endpoint: payload.endpoint,
      keys: payload.keys,
      topics,
      lang: 'km',
    })

    subscribed.value = true
    return true
  }

  async function unsubscribe(): Promise<void> {
    if (!supported.value) return
    const registration = await navigator.serviceWorker.ready
    const subscription = await registration.pushManager.getSubscription()
    if (!subscription) return

    await api.post('/api/push/unsubscribe', { endpoint: subscription.endpoint })
    await subscription.unsubscribe()
    subscribed.value = false
  }

  return { supported, permission, subscribed, subscribe, unsubscribe }
}
<script setup lang="ts">
/**
 * Notification opt-in (§30).
 *
 * Readers choose which topics they want rather than being subscribed to
 * everything — §30 is explicit that not every article should be a push.
 * The prompt appears only after a reader has spent time on the site, and a
 * dismissal is remembered.
 */

const { t } = useLocale()
const { supported, permission, subscribed, subscribe } = usePush()

const visible = ref(false)
const selected = ref<string[]>(['breaking'])
const busy = ref(false)

const STORAGE_KEY = 'cfn.push-prompt.dismissed'
const DELAY_MS = 25_000

// Computed so the labels follow the reader's language. The keys are the push
// topics the API accepts and never change with locale.
const topics = computed(() => [
  { key: 'breaking', label: t('topicBreaking') },
  { key: 'cambodia', label: t('topicCambodia') },
  { key: 'sports', label: t('topicSports') },
  { key: 'kun-khmer', label: t('topicKunKhmer') },
  { key: 'business', label: t('topicBusiness') },
  { key: 'technology', label: t('topicTechnology') },
  { key: 'entertainment', label: t('topicEntertainment') },
])

onMounted(() => {
  if (!supported.value || permission.value !== 'default' || subscribed.value) return
  try {
    if (localStorage.getItem(STORAGE_KEY)) return
  } catch {
    // Storage unavailable: show the prompt, it is still dismissible.
  }
  setTimeout(() => { visible.value = true }, DELAY_MS)
})

function dismiss() {
  visible.value = false
  try {
    localStorage.setItem(STORAGE_KEY, String(Date.now()))
  } catch { /* nothing to do */ }
}

function toggle(topic: string) {
  selected.value = selected.value.includes(topic)
    ? selected.value.filter(t => t !== topic)
    : [...selected.value, topic]
}

async function enable() {
  if (!selected.value.length) return
  busy.value = true
  try {
    await subscribe(selected.value)
  } finally {
    busy.value = false
    dismiss()
  }
}
</script>

<template>
  <div
    v-if="visible"
    class="fixed inset-x-4 bottom-4 z-50 mx-auto max-w-md rounded-xl border border-line bg-surface p-5 shadow-lift sm:inset-x-auto sm:right-4"
    role="dialog"
    aria-labelledby="push-prompt-heading"
  >
    <h2 id="push-prompt-heading" class="text-kh-base font-bold">{{ t('notifyHeading') }}</h2>
    <p class="mt-1 text-kh-sm text-ink-muted khmer-wrap">
      {{ t('notifyPickTopics') }}
    </p>

    <div class="mt-3 flex flex-wrap gap-2">
      <button
        v-for="topic in topics"
        :key="topic.key"
        :class="[
          'rounded-full border px-3 py-1.5 text-kh-sm transition-colors',
          selected.includes(topic.key)
            ? 'border-brand bg-brand text-white'
            : 'border-line hover:border-brand',
        ]"
        :aria-pressed="selected.includes(topic.key)"
        @click="toggle(topic.key)"
      >
        {{ topic.label }}
      </button>
    </div>

    <div class="mt-4 flex gap-2">
      <button
        class="flex-1 rounded-lg bg-brand px-4 py-2.5 font-semibold text-white hover:bg-brand-dark disabled:opacity-50"
        :disabled="busy || !selected.length"
        @click="enable"
      >
        {{ busy ? t('working') : t('notifyEnable') }}
      </button>
      <button class="rounded-lg border border-line px-4 py-2.5 font-semibold hover:bg-surface-muted" @click="dismiss">
        {{ t('notifyNoThanks') }}
      </button>
    </div>
  </div>
</template>
<script setup lang="ts">
const { t } = useLocale()
/**
 * The public site shell. The admin uses its own layout so the reader-facing
 * header, footer and breaking bar never render inside the CMS.
 */
</script>

<template>
  <div class="flex min-h-screen flex-col bg-surface">
    <!-- Keyboard users land here first; the nav is long, so a skip link is
         the difference between one tab and thirty. -->
    <a
      href="#main"
      class="sr-only focus:not-sr-only focus:absolute focus:left-4 focus:top-4 focus:z-[100]
             focus:rounded focus:bg-brand focus:px-4 focus:py-2 focus:text-white"
    >
      {{ t('skipToContent') }}
    </a>

    <OfflineBanner />
    <TheHeader />
    <BreakingNewsBar />

    <main id="main" class="flex-1">
      <slot />
    </main>

    <TheFooter />
    <MobileStickyAd />
    <PushNotificationPrompt />
  </div>
</template>
